class _AsyncChats:
    analysis: _AsyncChatsAnalysis
    items: _AsyncChatsItems
    messages: _AsyncChatsMessages
    tokens: _AsyncChatsTokens

    def __init__(self, transport: "AsyncTransport") -> None:
        self._t = transport
        self.analysis = _AsyncChatsAnalysis(transport)
        self.items = _AsyncChatsItems(transport)
        self.messages = _AsyncChatsMessages(transport)
        self.tokens = _AsyncChatsTokens(transport)

    async def create(
        self,
        *,
        agent: AgentConfig | None = OMIT,
        agent_id: str | None = OMIT,
        agent_override: AgentOverride | None = OMIT,
        agent_team: AgentTeam | None = OMIT,
        agent_version: int | Literal["draft"] | None = OMIT,
        contact_key: str | None = OMIT,
        userdata: Mapping[str, Any] | None = OMIT,
        vars: Mapping[str, str] | None = OMIT,
    ) -> ChatResponse:
        """Start a chat with a text agent. Send it messages with `create_chat_message`.

        It stays open until the agent's `end_call` tool or `end_chat` ends it. Starting
        one ends the contact's open chat with the same agent.

        Args:
            agent: A complete agent definition, run for this call and stored nowhere. Mutually
                exclusive with `agent_id`.
            agent_id: An agent in this workspace. Mutually exclusive with `agent`.
            agent_override: Changes layered on top of whichever base was named. Absent keys keep
                the base value, an explicit null clears the field, objects deep-merge and
                lists replace.
            agent_team: Run several agents on this call, defined here. Mutually exclusive with
                `agent_id` / `agent` / `agent_version` / `agent_override`.
            agent_version: Which version of `agent_id` to run. Omit for the published one.
                `"draft"` runs the unpublished working copy — validated and tool-pinned at
                request time, and refused with the publish errors if it does not hold
                together.
            vars: Values for the variables the agents on this session declare, read as
                {{vars.name}} in a prompt, a greeting and a tool. They override each agent's
                declared default and reach every agent the session runs, including a handoff
                target. Unlike `userdata`, which describes the PERSON and is kept on their
                contact record, these describe THIS session and are gone with it. Strings
                only; an empty string is a deliberate blank, not a request for the default.
                The model can see them, so put credentials in a workspace secret and read
                {{secrets.NAME}} from a tool instead.
        """
        return await self._t.request(
            "POST",
            "/v1/chats",
            body={
                "agent": agent,
                "agent_id": agent_id,
                "agent_override": agent_override,
                "agent_team": agent_team,
                "agent_version": agent_version,
                "contact_key": contact_key,
                "userdata": userdata,
                "vars": vars,
            },
        )

    async def delete(
        self,
        chat_id: str,
    ) -> None:
        """Erase an ended chat's content; the chat and its cost stay. Cannot be undone."""
        await self._t.request("DELETE", f"/v1/chats/{_p(chat_id)}", expect="none")

    async def detail(
        self,
        chat_id: str,
    ) -> ChatDetailResponse:
        """One chat with its health snapshot, cost lines, vars and event trace."""
        return await self._t.request("GET", f"/v1/chats/{_p(chat_id)}/detail")

    async def end(
        self,
        chat_id: str,
    ) -> ChatResponse:
        """End a chat. Its analysis and `session.completed` webhook follow."""
        return await self._t.request("POST", f"/v1/chats/{_p(chat_id)}/end")

    async def get(
        self,
        chat_id: str,
    ) -> ChatResponse:
        """Read one chat: its status, cost so far and, once ended, its analysis."""
        return await self._t.request("GET", f"/v1/chats/{_p(chat_id)}")

    async def list(
        self,
        *,
        limit: int = OMIT,
        offset: int = OMIT,
        agent_id: str | None = OMIT,
        contact_key: str | None = OMIT,
        status: Literal["open", "ended", "all"] = OMIT,
    ) -> PageChatResponse:
        """List chats, newest first.

        Omitted parameters take the server's default: limit=100, offset=0, status='all'.
        """
        return await self._t.request(
            "GET",
            "/v1/chats",
            query={
                "limit": limit,
                "offset": offset,
                "agent_id": agent_id,
                "contact_key": contact_key,
                "status": status,
            },
        )


