class _AsyncIntegrationsTriggers:
    def __init__(self, transport: "AsyncTransport") -> None:
        self._t = transport

    async def create(
        self,
        integration_id: str,
        *,
        trigger_type: Literal[
            "telegram.message.inbound",
            "whatsapp.message.inbound",
            "whatsapp.call.inbound",
        ],
        agent_id: str | None = OMIT,
        enabled: bool = OMIT,
        metadata: Mapping[str, Any] = OMIT,
        provider_subscription_ref: str | None = OMIT,
        reply_mode: Literal["public_reply", "internal_note", "none"] = OMIT,
    ) -> IntegrationTriggerResponse:
        """Deploy an agent to an inbound provider event.

        `reply_mode` decides what happens with the agent's answer: `public_reply`
        sends it to the customer, `internal_note` posts it privately where the
        provider supports that, `none` generates without sending.

        Enabling validates that the integration is active and the assigned agent is
        a published text agent, so create disabled while still wiring things up.
        """
        return await self._t.request(
            "POST",
            f"/v1/integrations/{_p(integration_id)}/triggers",
            body={
                "agent_id": agent_id,
                "enabled": enabled,
                "metadata": metadata,
                "provider_subscription_ref": provider_subscription_ref,
                "reply_mode": reply_mode,
                "trigger_type": trigger_type,
            },
        )

    async def delete(
        self,
        integration_id: str,
        trigger_id: str,
    ) -> OkResponse:
        """Delete a trigger permanently. The agent stops receiving that event."""
        return await self._t.request(
            "DELETE", f"/v1/integrations/{_p(integration_id)}/triggers/{_p(trigger_id)}"
        )

    async def list(
        self,
        integration_id: str,
        *,
        limit: int = OMIT,
        offset: int = OMIT,
    ) -> PageIntegrationTriggerResponse:
        """List the trigger deployments under an integration.

        A trigger binds an inbound provider event — a Telegram message — to a
        published agent version.

        Omitted parameters take the server's default: limit=200, offset=0.
        """
        return await self._t.request(
            "GET",
            f"/v1/integrations/{_p(integration_id)}/triggers",
            query={"limit": limit, "offset": offset},
        )

    async def update(
        self,
        integration_id: str,
        trigger_id: str,
        *,
        agent_id: str | None = OMIT,
        enabled: bool | None = OMIT,
        metadata: Mapping[str, Any] | None = OMIT,
        provider_subscription_ref: str | None = OMIT,
        reply_mode: Literal["public_reply", "internal_note", "none"] | None = OMIT,
        status: Literal["active", "disabled", "needs_setup", "error"] | None = OMIT,
        trigger_type: Literal[
            "telegram.message.inbound",
            "whatsapp.message.inbound",
            "whatsapp.call.inbound",
        ]
        | None = OMIT,
    ) -> IntegrationTriggerResponse:
        """Update a trigger: reassign the agent, change reply mode, enable or
        disable it.

        Omitted fields are left unchanged, and enabling one runs the same checks
        creating it did.
        """
        return await self._t.request(
            "PATCH",
            f"/v1/integrations/{_p(integration_id)}/triggers/{_p(trigger_id)}",
            body={
                "agent_id": agent_id,
                "enabled": enabled,
                "metadata": metadata,
                "provider_subscription_ref": provider_subscription_ref,
                "reply_mode": reply_mode,
                "status": status,
                "trigger_type": trigger_type,
            },
        )


class _AsyncIntegrations:
    mcp_tools: _AsyncIntegrationsMcpTools
    triggers: _AsyncIntegrationsTriggers

    def __init__(self, transport: "AsyncTransport") -> None:
        self._t = transport
        self.mcp_tools = _AsyncIntegrationsMcpTools(transport)
        self.triggers = _AsyncIntegrationsTriggers(transport)

    async def catalog(
        self,
        *,
        limit: int = OMIT,
        offset: int = OMIT,
    ) -> PageIntegrationCatalogItem:
        """List the providers that can be integrated, and how to connect each one.

        `auth_type` says which path a provider takes: `manual` through this API,
        `oauth` from the dashboard. `setup_fields` is the authoritative list of what
        each manual provider requires — read it rather than guessing. `capabilities`
        says whether it serves tools (MCP) or a messaging channel (triggers).

        Omitted parameters take the server's default: limit=200, offset=0.
        """
        return await self._t.request(
            "GET", "/v1/integrations/catalog", query={"limit": limit, "offset": offset}
        )

    async def create(
        self,
        *,
        display_name: str,
        provider: Literal[
            "custom_mcp",
            "google_calendar",
            "cal_com",
            "calendly",
            "asana",
            "jira",
            "hubspot",
            "exa",
            "tavily",
            "resend",
            "rocketreach",
            "telegram",
            "whatsapp",
        ],
        allowed_tools: Sequence[str] | None = OMIT,
        credentials_ref: str | None = OMIT,
        mcp_config: Mapping[str, Any] = OMIT,
        metadata: Mapping[str, Any] = OMIT,
        provider_account_info: Mapping[str, Any] = OMIT,
        tools_namespace: str | None = OMIT,
        webhook_config: Mapping[str, Any] = OMIT,
    ) -> IntegrationResponse:
        """Create a manual integration, fully configured.

        Which of `credentials_ref`, `provider_account_info`, `mcp_config` and
        `webhook_config` a provider needs is described by its `setup_fields` in the
        integration catalog. Secret-bearing fields take a plaintext value — stored
        as a workspace secret — or an existing `{{secrets.NAME}}` reference.

        Leave `allowed_tools` unset to expose every tool the server lists. OAuth
        providers are connected from the dashboard instead.
        """
        return await self._t.request(
            "POST",
            "/v1/integrations",
            body={
                "allowed_tools": allowed_tools,
                "credentials_ref": credentials_ref,
                "display_name": display_name,
                "mcp_config": mcp_config,
                "metadata": metadata,
                "provider": provider,
                "provider_account_info": provider_account_info,
                "tools_namespace": tools_namespace,
                "webhook_config": webhook_config,
            },
        )

    async def delete(
        self,
        integration_id: str,
    ) -> OkResponse:
        """Delete an integration and its triggers permanently."""
        return await self._t.request("DELETE", f"/v1/integrations/{_p(integration_id)}")

    async def get(
        self,
        integration_id: str,
    ) -> IntegrationResponse:
        """Fetch one integration: provider, status, structured config, trigger
        capabilities and inbound webhook setup state.
        """
        return await self._t.request("GET", f"/v1/integrations/{_p(integration_id)}")

    async def list(
        self,
        *,
        limit: int = OMIT,
        offset: int = OMIT,
    ) -> PageIntegrationResponse:
        """List the workspace's integrations with their provider, status and config.

        Secret values are never returned — credential fields come back as
        `{{secrets.NAME}}` references.

        Omitted parameters take the server's default: limit=200, offset=0.
        """
        return await self._t.request(
            "GET", "/v1/integrations", query={"limit": limit, "offset": offset}
        )

    async def update(
        self,
        integration_id: str,
        *,
        allowed_tools: Sequence[str] | None = OMIT,
        credentials_ref: str | None = OMIT,
        display_name: str | None = OMIT,
        mcp_config: Mapping[str, Any] | None = OMIT,
        metadata: Mapping[str, Any] | None = OMIT,
        provider_account_info: Mapping[str, Any] | None = OMIT,
        status: Literal["active", "disabled", "needs_reconnect", "error"] | None = OMIT,
        tools_namespace: str | None = OMIT,
        webhook_config: Mapping[str, Any] | None = OMIT,
    ) -> IntegrationResponse:
        """Update an integration. Omitted fields are left unchanged.

        Sending `credentials_ref` rotates the credential. Only `active` integrations
        can be attached to agents or serve triggers.

        `allowed_tools` replaces the approved list wholesale: exactly those tools
        become callable by every agent this integration is attached to. It cannot be
        emptied — an agent that should call nothing is an integration that should be
        disabled.
        """
        return await self._t.request(
            "PATCH",
            f"/v1/integrations/{_p(integration_id)}",
            body={
                "allowed_tools": allowed_tools,
                "credentials_ref": credentials_ref,
                "display_name": display_name,
                "mcp_config": mcp_config,
                "metadata": metadata,
                "provider_account_info": provider_account_info,
                "status": status,
                "tools_namespace": tools_namespace,
                "webhook_config": webhook_config,
            },
        )


class _AsyncObservability:
    def __init__(self, transport: "AsyncTransport") -> None:
        self._t = transport

    async def get(
        self,
        *,
        start_date: str | None = OMIT,
        end_date: str | None = OMIT,
        timezone: str = OMIT,
        agent_id: str | None = OMIT,
        channel: AgentChannel | None = OMIT,
    ) -> ObservabilityResponse:
        """Workspace analytics: volume, endings, recordings, response time and spend.
        One snapshot of a date range, up to 7 days.

        `summary` is the range total, `daily` one row per day, and `volume` the same
        days cut by dimension (agent, phone number, type, status, close reason,
        recording, analysis, transfer) — each capped at eight series with the tail
        rolled into `Other`. `latency` reports response time per model stage and
        `cost` breaks the bill down by stage, provider and model.

        Narrow it with `agent_id` and `channel`; `timezone` decides day boundaries.

        Two traps. `latency.basis` is `per_turn` for voice and video and `per_call`
        for text, so the two are never averaged into one number. And every rate is
        over a subset — `success_rate` over `judged_sessions`, `cost` over
        `priced_sessions`, latency over `measured_sessions`.

        Omitted parameters take the server's default: timezone='UTC'.
        """
        return await self._t.request(
            "GET",
            "/v1/observability",
            query={
                "start_date": start_date,
                "end_date": end_date,
                "timezone": timezone,
                "agent_id": agent_id,
                "channel": channel,
            },
        )


class _AsyncProviderKeys:
    def __init__(self, transport: "AsyncTransport") -> None:
        self._t = transport

    async def delete(
        self,
        provider: str,
    ) -> OkResponse:
        """Remove this organization's API key for one provider. Agents that need it
        will stop working and can no longer be published. Organization admins only.
        """
        return await self._t.request("DELETE", f"/v1/byok/{_p(provider)}")

    async def list(
        self,
    ) -> ProviderKeysResponse:
        """List every AI provider and whether this workspace has an API key for it.

        Talqing is strict BYOK: agents run on the workspace's own provider keys.
        Publishing fails if the agent needs a provider with no key configured.
        Every key listed here was accepted by its provider when it was saved.
        """
        return await self._t.request("GET", "/v1/byok")

    async def set(
        self,
        provider: str,
        *,
        api_key: str,
    ) -> ProviderKeyResponse:
        """Store this workspace's API key for one provider, replacing any existing key.

        The key is called against the provider first and only stored if accepted: a
        rejected key is a 400 that leaves any existing key untouched, and a provider
        that cannot be reached is a 502. Encrypted at rest and never returned.
        Organization admins only.
        """
        return await self._t.request(
            "PUT", f"/v1/byok/{_p(provider)}", body={"api_key": api_key}
        )


class _AsyncSchemasFunctions:
    def __init__(self, transport: "AsyncTransport") -> None:
        self._t = transport

    async def get(
        self,
        name: str,
    ) -> FunctionArgumentsResponse:
        """The full argument schema of one function, by name.

        Every function's arguments are fetched here rather than shown up front, so
        call this before the first time you use one. Two exceptions, which carry
        their own shape because they would otherwise be uncallable: this function
        and `describe_schema`.
        """
        return await self._t.request("GET", f"/v1/schemas/functions/{_p(name)}")


class _AsyncSchemas:
    functions: _AsyncSchemasFunctions

    def __init__(self, transport: "AsyncTransport") -> None:
        self._t = transport
        self.functions = _AsyncSchemasFunctions(transport)

    async def get(
        self,
        name: Literal[
            "AgentConfig", "AgentOverride", "AgentTeam", "TaskConfig", "ToolOperations"
        ],
    ) -> SchemaDocumentResponse:
        """The full JSON Schema of one of the five large request types.

        An argument whose description ends in `describe_schema('X')` carries only a
        placeholder for its shape — fetch the real one here before writing it.

        - `AgentConfig` — a whole agent definition; what `create_agent` takes.
        - `AgentOverride` — the same tree, every field optional: one call, or an update.
        - `AgentTeam` — several agents on one call, handing off to each other.
        - `TaskConfig` — an agent task: inputs, output shape, model stack.
        - `ToolOperations` — the operation tree a custom tool runs.

        These compose, so a document you fetch may itself defer to another.
        """
        return await self._t.request("GET", f"/v1/schemas/{_p(name)}")


